import type {PickerRepository} from '@github-ui/repos-picker'
import {MultiSelectReposPickerDialog} from '@github-ui/repos-picker'
import {GearIcon} from '@primer/octicons-react'
import {IconButton} from '@primer/react'
import {useRef, useState} from 'react'

export interface ActionsReposPickerProps {
  orgName: string
  selectedRepos: PickerRepository[]
  inputName: string
  autoSubmitForm: boolean
}

export function ActionsReposPicker(props: ActionsReposPickerProps) {
  const {orgName, selectedRepos: initialSelectedRepos, inputName, autoSubmitForm} = props
  const [selected, setSelected] = useState<PickerRepository[]>(initialSelectedRepos)
  const [isDialogOpen, setIsDialogOpen] = useState(false)
  const buttonRef = useRef<HTMLButtonElement>(null)
  const containerRef = useRef<HTMLDivElement>(null)

  const handleSubmit = (repos: PickerRepository[]) => {
    setSelected(repos)
    setIsDialogOpen(false)

    if (autoSubmitForm) {
      const form = containerRef.current?.closest('form') as HTMLFormElement | null
      if (form) {
        requestAnimationFrame(() => form.submit())
      }
    }
  }

  const count = selected.length

  return (
    <div ref={containerRef} className="d-flex flex-items-center">
      {/* Hidden inputs for Rails form submission */}
      {selected.map(repo => (
        <input key={repo.id} type="hidden" name={inputName} value={repo.nodeId} />
      ))}

      <span className="mr-1 color-fg-muted">
        {count === 0 && <span>No repositories selected</span>}
        {count === 1 && <span>1 selected repository</span>}
        {count > 1 && <span>{count} selected repositories</span>}
      </span>

      <IconButton
        ref={buttonRef}
        icon={GearIcon}
        aria-label="Select repositories"
        variant="invisible"
        onClick={() => setIsDialogOpen(true)}
      />

      {isDialogOpen && (
        <MultiSelectReposPickerDialog
          scope={{type: 'organization', slug: orgName}}
          selected={selected}
          onSubmit={handleSubmit}
          onDismiss={() => setIsDialogOpen(false)}
          returnFocusRef={buttonRef}
        />
      )}
    </div>
  )
}
